INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cf7d', 'Asparagus', 8, 'szt', 10);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cf7d', 'Rye Bread', 4, 'szt', 11);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cf7d', 'Butter', 1, 'szt', 12);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cf7d', 'västerbottensost cheese', 100, 'g', 13);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cf7d', 'Dill', 1, 'szt', 14);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cf7d', 'Salt', 1, 'szt', 15);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cf7d', 'Black Pepper', 1, 'szt', 16);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf7d', 1, 'To make the horseradish cream, mix the crème fraîche, grated horseradish, lemon juice, salt and white pepper in a bowl. Refrigerate until serving.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf7d', 2, 'To make the crispy shallots, heat some vegetable oil in a frying pan over a medium heat. Add the sliced shallots and fry until golden brown and crispy.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf7d', 3, 'Remove with a slotted spoon and drain on a plate lined with kitchen paper. Season with a pinch of salt.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf7d', 4, 'To make the open sandwich, bring a large saucepan of salted water to the boil, then blanch half of the asparagus (four white and four green) until tender-crisp, about 2–3 minutes.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf7d', 5, 'Add ice to a bowl of cold water. Use a slotted spoon to remove the asparagus from the boiling water and immediately transfer to the iced water to stop cooking. Thinly slice the remaining asparagus lengthwise to serve raw.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf7d', 6, 'Pre-heat the grill until hot. Spread the rye bread with butter and grill until golden and crisp.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf7d', 7, 'To serve, place the grilled bread slices on serving plates. Arrange both the blanched and raw asparagus on the bread. Drizzle with horseradish cream, then sprinkle grated cheese over the top. Garnish with the crispy shallots and some fresh dill to finish.');
INSERT INTO recipes (id, name, description, meal_type, servings) VALUES ('00000000-0000-4000-8000-00000000cfb4', 'Patatas bravas', 'Danie: Spanish. Źródło: TheMealDB', 'lunch', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cfb4', 'Olive Oil', 45, 'ml', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cfb4', 'Onion', 1, 'szt', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cfb4', 'Garlic', 2, 'szt', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cfb4', 'Tinned Tomatos', 225, 'g', 4);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cfb4', 'Tomato Puree', 15, 'ml', 5);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cfb4', 'Paprika', 10, 'ml', 6);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cfb4', 'Chilli Powder', 1, 'szt', 7);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cfb4', 'Sugar', 1, 'szt', 8);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cfb4', 'Parsley', 1, 'szt', 9);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cfb4', 'Potatoes', 900, 'g', 10);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cfb4', 'Olive Oil', 30, 'ml', 11);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cfb4', 1, 'step 1');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cfb4', 2, 'Heat the oil in a pan and fry the onion for about 5 mins until softened. Add the garlic, chopped tomatoes, tomato purée, sweet paprika, chilli powder, sugar and a pinch of salt, then bring to the boil, stirring occasionally. Lower to a simmer and cook for 10 mins until pulpy. Can be kept chilled for up to 24 hrs.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cfb4', 3, 'step 2');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cfb4', 4, 'Heat oven to 200C/180C fan/gas 6. Pat the potatoes dry with kitchen paper, then tip into a roasting tin and toss in the olive oil and some seasoning. Roast for 40-50 mins until crisp and golden. Tip the potatoes into serving dishes and spoon over the tomato sauce. Sprinkle with some fresh parsley to serve.');
INSERT INTO recipes (id, name, description, meal_type, servings) VALUES ('00000000-0000-4000-8000-00000000cfa8', 'Pisto con huevos', 'Danie: Spanish. Źródło: TheMealDB', 'lunch', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cfa8', 'Olive Oil', 2, 'szt', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cfa8', 'Onion', 2, 'szt', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cfa8', 'Garlic Clove', 4, 'szt', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cfa8', 'Mixed peppers', 5, 'szt', 4);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cfa8', 'Oregano', 5, 'ml', 5);
